def check_inclusion(small, big):
    from collections import Counter
    k = len(small)
    need = Counter(small)
    win = Counter(big[:k])
    if win == need:
        return True
    for i in range(k, len(big)):
        win[big[i]] += 1
        win[big[i - k]] -= 1
        if win[big[i - k]] == 0:
            del win[big[i - k]]
        if win == need:
            return True
    return False
